floor_fn:
"""
    Simulation to math.log with base e
    No doctests needed
    """
def log(x: Any) -> object {
    n = 10000000000.0;
    return (n * ((x ** (1 / n)) - 1));
}

test_blocks:
test "t0" {
    assert (log(1) == 0.0);;
}

test "t1" {
    assert (log(1) == 0);;
}

test "t2" {
    assert (log(1.0) == log(int(1.0)));;
}

test "t3" {
    assert (log(1) == log(float(1)));;
}
